.tag {
    display: inline-block;
    border: 1px solid;
    padding: 0 0.5em 0 0.5em;
    margin: 0.3em;
    border-radius: 1em;
    text-transform: lowercase;
    font-variant: small-caps;
    background: white;
    font-weight: bold;
    letter-spacing: 0.5px;
    color: black;
}

